css:
.action-banner a[href*="frappe.utils.print_format.download_pdf"] {
    display: none !important;
}

.print-format{
    font-family: "Times New Roman" !important;
}

.tab { 
    text-indent: 50px;
}

@page { size: A4; margin: 18mm 20mm; }
body {
    font-family: "Times New Roman" !important;
    font-size: 12pt;
    line-height: 1;
    color: #000;
}
.center { text-align: center; }
.underline {
    display: inline-block;
    border-bottom: 1px solid #000;
    padding: 0 4px;
    min-width: 180px;
}
.small { font-size: 9pt; }
.label-small { font-size: 9pt; font-style: italic; }
.spacer { height: 10px; }
.sig-line {
    border-bottom: 1px solid #000;
    width: 280px;
    height: 18px;
    margin: 0 auto;
}
